def apply(inputs,premises):
    observation=inputs.get('observation')
    if observation is None:
        return {'bindings':[],'unresolved':['The factual observation has not been read']}
    bindings=[]
    unresolved=[]
    views=observation.get('views')
    if not isinstance(views,list):
        return {'bindings':[],'unresolved':['No coherent factual views were supplied']}
    for view in views:
        bound={}
        person=view.get('query_person')
        year=view.get('query_year')
        if isinstance(person,str):
            bound['query_person']=person
        else:
            unresolved.append('The queried person is unread or unresolved')
        if type(year) is int:
            bound['query_year']=year
        else:
            unresolved.append('The queried year is unread or unresolved')
        marriages=view.get('marriage_facts')
        if isinstance(marriages,list):
            rows=[]
            for record in marriages:
                form=record.get('form')
                end=None
                opened=False
                if form=='ongoing_since':
                    opened=True
                elif form=='closed_interval':
                    end=record.get('end_date')
                rows.append({'individual':record.get('individual'),'spouse':record.get('spouse'),'start_date':record.get('start_date'),'end_date':end,'open_ended':opened})
            bound['marriage_intervals']=rows
        else:
            unresolved.append('Marriage facts are unread or unresolved')
        decrees=view.get('decree_facts')
        if isinstance(decrees,list):
            rows=[]
            for record in decrees:
                form=record.get('form')
                end=None
                opened=False
                if form=='ongoing_from':
                    opened=True
                elif form=='closed_interval':
                    end=record.get('end_date')
                rows.append({'individual':record.get('individual'),'spouse':record.get('spouse'),'decree_type':record.get('decree_type'),'effective_date':record.get('effective_date'),'end_date':end,'open_ended':opened})
            bound['legal_separation_decrees']=rows
        else:
            unresolved.append('Legal-separation decree facts are unread or unresolved')
        returns=view.get('return_records')
        items=view.get('itemization_records')
        if isinstance(returns,list):
            bound['return_records']=returns
        else:
            unresolved.append('Return facts are unread or unresolved')
        if isinstance(items,list):
            bound['itemization_records']=items
        else:
            unresolved.append('Itemized-deduction facts are unread or unresolved')
        bindings.append({'inputs':bound,'witnesses':view.get('witnesses')})
    return {'bindings':bindings,'unresolved':sorted(set(unresolved))}
